#include "Atr.h"
#include "Internal.h"
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
#include <algorithm>
#include <iomanip>
#include <sstream>
namespace RetroMediaLab::MediaEngine::Atr {
namespace {
using namespace Constants;using Internal::word;using Internal::declared;
bool padding(MediaFileSystems::Bytes b){return !b.empty()&&(std::all_of(b.begin(),b.end(),[](auto v){return v==ZeroPadding;})||std::all_of(b.begin(),b.end(),[](auto v){return v==ExternalPadding;}));}
bool headerInclusive(std::uint32_t size,std::uint64_t length,std::size_t observed){const auto boot=std::uint64_t(bootAreaLength(std::int32_t(size)));return length==observed+HeaderSize&&length<=MaxLength&&length>=boot&&(length-boot)%size==0;}
bool external(MediaFileSystems::Bytes bytes,std::uint32_t size,std::uint64_t length,std::size_t observed){const auto boot=std::uint64_t(bootAreaLength(std::int32_t(size)));return length>0&&length<observed&&length<=MaxLength&&length>=boot&&(length-boot)%size==0&&padding(bytes.subspan(HeaderSize+std::size_t(length)));}
bool truncated(MediaFileSystems::Bytes b,std::uint32_t size,std::uint64_t length,std::size_t observed){if(size!=SingleSize||observed<SingleSize||observed>=StandardCount*SingleSize||length<=observed||length>StandardCount*SingleSize)return false;const auto boot=b[HeaderSize+BootCountOffset];return boot>0&&std::uint32_t(boot)*SingleSize<=observed;}
bool mislabeled(MediaFileSystems::Bytes b,std::uint32_t size,std::uint64_t length,std::size_t observed){if(size!=SingleSize||observed!=EnhancedCount*SingleSize||length!=ExtendedCount*SingleSize)return false;const auto vtoc=HeaderSize+(VtocSector-FirstSector)*SingleSize,directory=vtoc+SingleSize;if(b.size()<directory+1||(b[directory]&DirectoryMask)==0)return false;const auto managed=word(b,vtoc+ManagedCountOffset);return (b[vtoc]==VtocDos2&&managed==EnhancedUsable)||(b[vtoc]==VtocDos3&&managed==XfManaged);}
std::string signature(std::uint16_t value){std::ostringstream text;text<<std::hex<<std::uppercase<<std::setfill(HexFill)<<std::setw(SignatureHexWidth)<<value;return std::string(HexPrefix)+text.str();}
}
bool supportedSectorSize(std::int32_t size) noexcept{return size==Constants::SingleSize||size==Constants::DoubleSize||size==Constants::ExtendedSize;}
std::int32_t bootAreaLength(std::int32_t size) noexcept{return size==Constants::SingleSize?0:Constants::BootCount*Constants::SingleSize;}
std::int32_t sectorCount(std::int32_t payload,std::int32_t size){if(size==0)throw MediaError(DiagnosticCode::AtrSectorCount,{std::to_string(size),std::to_string(payload)});return (size==Constants::SingleSize?0:std::int32_t(Constants::BootCount))+(payload-bootAreaLength(size))/size;}
bool truncatedSingleDensity(std::int32_t size,std::int32_t count) noexcept{return size==Constants::SingleSize&&count>0&&count<std::int32_t(Constants::StandardCount);}
std::size_t usablePayloadLength(MediaFileSystems::Bytes b){using namespace Constants;if(b.size()<HeaderSize)throw MediaError(DiagnosticCode::AtrHeader,{std::to_string(b.size()),std::to_string(HeaderSize),std::string(UnknownSignature),signature(Signature)});const auto size=word(b,SectorSizeOffset);if(!size)throw MediaError(DiagnosticCode::AtrUnsupportedSize,{std::to_string(size),std::string(SectorSizes)});const auto observed=b.size()-HeaderSize;const auto length=declared(b);if(headerInclusive(size,length,observed)||external(b,size,length,observed))return std::size_t(length);if(size!=DoubleSize||observed!=StandardCount*size)return observed;const auto standard=BootCount*SingleSize+(StandardCount-BootCount)*size;const auto tail=b.subspan(HeaderSize+standard);return std::all_of(tail.begin(),tail.end(),[](auto v){return v==ZeroPadding;})?standard:observed;}
void validate(MediaFileSystems::Bytes b){using namespace Constants;if(b.size()<HeaderSize||word(b,SignatureOffset)!=Signature)throw MediaError(DiagnosticCode::AtrHeader,{std::to_string(b.size()),std::to_string(HeaderSize),b.size()<sizeof(std::uint16_t)?std::string(UnknownSignature):signature(word(b,SignatureOffset)),signature(Signature)});const auto size=word(b,SectorSizeOffset);if(!supportedSectorSize(size))throw MediaError(DiagnosticCode::AtrUnsupportedSize,{std::to_string(size),std::string(SectorSizes)});const auto length=declared(b),observed=b.size()-HeaderSize,usable=usablePayloadLength(b);const bool recoverable=length!=observed&&(truncated(b,size,length,observed)||mislabeled(b,size,length,observed)||headerInclusive(size,length,observed));const bool padded=length!=observed&&external(b,size,length,observed);if(length!=observed&&!recoverable&&!padded)throw MediaError(DiagnosticCode::AtrPayloadLength,{std::to_string(observed),std::to_string(length)});const auto boot=std::size_t(bootAreaLength(size));if(!recoverable&&(usable<boot||(usable-boot)%size))throw MediaError(DiagnosticCode::AtrTruncatedPayload,{std::to_string(observed),std::to_string(boot),std::to_string(size)});}
}
